        import math

def _intersection_ratio_from_barycentric(u, v, w):
    # Map to the standard reference triangle with vertices A(0,0), B(1,0), C(0,1)
    # For barycentric weights (alpha, beta, gamma) proportional to (u, v, w),
    # the Euclidean coordinates are x = beta, y = gamma with alpha + beta + gamma = 1.
    S = u + v + w
    if S <= 0:
        return None
    alpha = u / S
    beta = v / S
    gamma = w / S
    # Ensure strict interior and proper hexagon: all weights in (0, 1/2)
    if not (0 < alpha < 0.5 and 0 < beta < 0.5 and 0 < gamma < 0.5):
        return None
    # Define the half-turn image constraints for the standard triangle
    a2 = 2.0 * beta        # x <= a2
    b2 = 2.0 * gamma       # y <= b2
    c2 = 1.0 - 2.0 * alpha # x + y >= c2
    # In the standard triangle, intersection region is:
    # 0 <= x <= X, 0 <= y <= min(b2, 1 - x), and y >= max(0, c2 - x), where X = min(a2, 1).
    X = min(a2, 1.0)
    # Build breakpoints where U or L changes: x = 1 - b2 and x = c2, plus 0 and X.
    pts = [0.0, X, 1.0 - b2, c2]
    pts = sorted(pts)
    total = 0.0
    for i in range(len(pts) - 1):
        l = max(0.0, pts[i])
        r = min(X, pts[i + 1])
        if r <= l:
            continue
        xm = 0.5 * (l + r)
        # Determine which branch we're on using a midpoint test
        U_is_b = (xm <= 1.0 - b2)  # U = b2 else U = 1 - x
        L_is_c = (xm < c2)         # L = c2 - x else L = 0
        if U_is_b and L_is_c:
            # U = b2, L = c2 - x => f(x) = b2 - c2 + x
            total += (b2 - c2) * (r - l) + 0.5 * (r * r - l * l)
        elif U_is_b and (not L_is_c):
            # U = b2, L = 0 => f(x) = b2
            total += b2 * (r - l)
        elif (not U_is_b) and L_is_c:
            # U = 1 - x, L = c2 - x => f(x) = 1 - c2 (constant)
            total += (1.0 - c2) * (r - l)
        else:
            # U = 1 - x, L = 0 => f(x) = 1 - x
            total += (r - l) - 0.5 * (r * r - l * l)
    # Intersection area in the standard triangle of area 1/2
    I_std = max(total, 0.0)
    # Ratio r(P) = (intersection area)/(triangle area) = I_std / (1/2) = 2 * I_std
    return 2.0 * I_std


def verifier(assign):
    # Validate keys
    required = ['ab', 'bc', 'ca', 'u', 'v', 'w']
    for k in required:
        if k not in assign:
            # Missing data
            return (False, None)
    ab = assign['ab']; bc = assign['bc']; ca = assign['ca']
    u = assign['u']; v = assign['v']; w = assign['w']
    # Domain checks: positive integers for sides and weights
    if not all(isinstance(x, int) and x > 0 for x in [ab, bc, ca, u, v, w]):
        return (False, None)
    # Triangle inequality
    if not (ab + bc > ca and ab + ca > bc and bc + ca > ab):
        return (False, None)
    # Heron area
    s = 0.5 * (ab + bc + ca)
    a1 = s * (s - ab) * (s - bc) * (s - ca)
    if a1 <= 0:
        return (False, None)
    area_ABC = math.sqrt(a1)
    # Enforce difficulty: interior point with hexagonal overlap and non-centroid
    S = u + v + w
    if S <= 0:
        return (False, None)
    # Each weight strictly less than half of sum and not all equal
    if not (2 * max(u, v, w) < S and len({u, v, w}) > 1):
        return (False, None)
    # Also avoid near-degenerate overlap by requiring each weight at least 10% of the sum
    if min(u, v, w) * 10 < S:
        return (False, None)
    # Compute intersection ratio r(P)
    rP = _intersection_ratio_from_barycentric(u, v, w)
    if rP is None:
        return (False, None)
    # Union area = area(ABC) * (2 - r(P))
    union_area = area_ABC * (2.0 - rP)
    return (True, union_area)


